// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ComponentRun) predicate.ComponentRun {
	return predicate.ComponentRun(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ComponentRun) predicate.ComponentRun {
	return predicate.ComponentRun(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ComponentRun) predicate.ComponentRun {
	return predicate.ComponentRun(sql.NotPredicates(p))
}
